def topo_sort(graph):
    nodes = set()
    in_degree = {}
    adj = {}

    for src in graph:
        nodes.add(src)
        if src not in in_degree:
            in_degree[src] = 0
        if src not in adj:
            adj[src] = set()
        for dst in graph[src]:
            nodes.add(dst)
            if dst not in in_degree:
                in_degree[dst] = 0
            if dst not in adj:
                adj[dst] = set()
            adj[src].add(dst)

    for src in graph:
        for dst in graph[src]:
            in_degree[dst] += 1

    import heapq
    heap = []
    for node in nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Döngü tespit edildi")

    return result
